let cached: Set<string> | null = null;

/** Celý slovník jako sada. Lazy — první volání ji postaví, pak cachuje. */
export function czechWordSet(): Set<string> {
  if (!cached) {
    cached = new Set(CZECH_WORDS_RAW.split("\n"));
  }
  return cached;
}

/**
 * Je token skutečné české slovo? Normalizace: trim + malá písmena
 * cs-CZ, diakritika Zachována (viz header — složený index koliduje).
 */
export function isCzechWord(token: string): boolean {
  const normalized = token.trim().toLocaleLowerCase("cs-CZ");
  if (!normalized) return false;
  return czechWordSet().has(normalized);
}

/**
 * Je fráze (slovo nebo skupinová rýma) tvořena POUZE skutečnými
 * českými slovy? Každý token musí projít `isCzechWord`.
 */
export function isRealCzechPhrase(phrase: string): boolean {
  const tokens = phrase.trim().split(/\s+/).filter(Boolean);
  if (!tokens.length) return false;
  return tokens.every((token) => isCzechWord(token));
}

/**
 * Konečná validace rýmů: z každé sady nechá jen záznamy tvořené
 * reálnými českými slovy. Vrací i vyhozené (jdou do zpřesněného
 * promptu při opakování). Deterministické, závislost-free.
 */
export function filterRealCzechRhymes<T extends string>(
  list: T[],
): { kept: T[]; dropped: T[] } {
  const kept: T[] = [];
  const dropped: T[] = [];
  for (const entry of list) {
    if (isRealCzechPhrase(entry)) kept.push(entry);
    else dropped.push(entry);
  }
  return { kept, dropped };
}
